def transform(grid):
    H,W=len(grid),len(grid[0])
    out=[[0]*W for _ in range(H)]
    paths={}
    for r in range(H):
        for c in range(W):
            v=grid[r][c]
            if v:
                cells=[(r+dr,c+dc) for dr,dc in PATHS[v]]
                paths[v]=cells
                out[r][c]=v
                out[cells[-1][0]][cells[-1][1]]=v
                for rr,cc in cells[1:-1]:
                    out[rr][cc]=5
    # find crossings
    from collections import Counter
    cnt=Counter(cell for cs in paths.values() for cell in cs)
    crosses=[cell for cell,n in cnt.items() if n>1]
    for r,c in crosses:
        out[r][c]=4
        rr,cc=r,c
        while rr+1<H and cc-1>=0:
            rr,cc=rr+1,cc-1
            out[rr][cc]=4
    return out

